parts.text:
{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Introductory lead-in ('No driver shall—') that establishes no independent requirement on its own, serving only to govern the driver prohibitions set forth in paragraphs (a)(1) through (a)(3)."
    },
    {
      "quote_ref": "F001",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall use alcohol, as defined in § 382.107 of this subchapter, or be under the influence of alcohol, within 4 hours before going on duty or operating, or having physical control of, a commercial motor vehicle."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall use alcohol, be under the influence of alcohol, or have any measured alcohol concentration or detected presence of alcohol, while on duty, or operating, or in physical control of a commercial motor vehicle."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F000"],
      "kind": "prohibition",
      "meaning": "No driver shall be on duty or operate a commercial motor vehicle while the driver possesses wine of not less than one-half of one per centum of alcohol by volume, beer as defined in 26 U.S.C. 5052(a) of the Internal Revenue Code of 1954, or distilled spirits as defined in section 5002(a)(8) of such Code, except as provided for manifested shipments or bus passengers."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F000", "F003"],
      "kind": "exception",
      "meaning": "The prohibition against possessing wine, beer, or distilled spirits while on duty or operating a commercial motor vehicle does not apply to possession of wine, beer, or distilled spirits that are manifested and transported as part of a shipment."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F000", "F003"],
      "kind": "exception",
      "meaning": "The prohibition against possessing wine, beer, or distilled spirits while on duty or operating a commercial motor vehicle does not apply to possession of wine, beer, or distilled spirits that are possessed or used by bus passengers."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Introductory lead-in ('No motor carrier shall require or permit a driver to—') that establishes no independent requirement on its own, serving only to govern the motor carrier prohibitions set forth in paragraphs (b)(1) and (b)(2)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "No motor carrier shall require or permit a driver to violate any provision of paragraph (a) of 49 CFR 392.5."
    },
    {
      "quote_ref": "F008:F009",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "No motor carrier shall require or permit a driver to be on duty or operate a commercial motor vehicle if, by the driver's general appearance or conduct or by other substantiating evidence, the driver appears to have used alcohol within the preceding four hours."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Any driver who is found to be in violation of the provisions of paragraph (a) or (b) of 49 CFR 392.5 shall be placed out-of-service immediately for a period of 24 hours."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F010"],
      "kind": "statement",
      "meaning": "The 24-hour out-of-service period will commence upon issuance of an out-of-service order."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "No driver shall violate the terms of an out-of-service order issued under 49 CFR 392.5."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Introductory lead-in ('Any driver who is issued an out-of-service order under this section shall:') that establishes no independent duty on its own, serving only to govern the driver reporting requirements set forth in paragraphs (d)(1) and (d)(2)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "Any driver who is issued an out-of-service order under 49 CFR 392.5 shall report such issuance to his or her employer within 24 hours."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "Any driver who is issued an out-of-service order under 49 CFR 392.5 shall report such issuance to a State official, designated by the State that issued the driver's license, within 30 days unless the driver chooses to request a review of the order."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "If a driver who is issued an out-of-service order under 49 CFR 392.5 chooses to request a review of the order, the driver shall report the order to the designated State official within 30 days of an affirmation of the order by either the Division Administrator or State Director for the geographical area or the Administrator."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "Any driver who is subject to an out-of-service order under 49 CFR 392.5 may petition for review of that order by submitting a petition for review in writing within 10 days of the issuance of the order to the Division Administrator or State Director for the geographical area in which the order was issued."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The Division Administrator or State Director for the geographical area in which an out-of-service order was issued may affirm or reverse the order."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "Any driver adversely affected by an order of the Regional Director of Motor Carriers affirming or reversing the out-of-service order may petition the Administrator for review in accordance with 49 CFR 386.13."
    }
  ]
}
